from pathlib import Path
import json,sys,re
home=Path.home()
unitdir=home/".config/systemd/user"
units={}
for p in sorted(unitdir.glob("prediction-*")) if unitdir.exists() else []:
    if "a2z-v4" in p.name or "codex-supervisor" in p.name:
        try: txt=p.read_text(errors="replace")
        except Exception: txt=""
        units[p.name]=txt

a2z_timers={k:v for k,v in units.items() if "a2z-v4" in k and k.endswith(".timer")}
a2z_services={k:v for k,v in units.items() if "a2z-v4" in k and k.endswith(".service")}
general_timer=units.get("prediction-codex-supervisor.timer","")
general_service=units.get("prediction-codex-supervisor.service","")

def root_hint(txt):
    m=re.search(r'--root\s+([^\s]+)',txt)
    return m.group(1) if m else None

summary={
 "a2z_timer_count":len(a2z_timers),
 "a2z_service_count":len(a2z_services),
 "a2z_timers":sorted(a2z_timers),
 "a2z_services":sorted(a2z_services),
 "general_timer_present":bool(general_timer),
 "general_service_present":bool(general_service),
 "general_service_root":root_hint(general_service),
 "general_service_mentions_campaign":"FULL-A2Z-LIVE-20261004-V4" in general_service,
 "general_service_mentions_tick":" tick" in general_service or " tick " in general_service,
}
print("E131_CLASS "+json.dumps(summary,separators=(",",":")),flush=True)

if a2z_timers:
    print("E131=A2Z_TIMER_PRESENT",flush=True); raise SystemExit(20)
if general_timer and general_service and "FULL-A2Z-LIVE-20261004-V4" in general_service:
    print("E131=GENERAL_TIMER_TICKS_A2Z_CAMPAIGN",flush=True); raise SystemExit(21)
if general_timer and general_service:
    print("E131=NO_A2Z_TIMER_GENERAL_TIMER_OTHER_ROOT",flush=True); raise SystemExit(22)
print("E131=NO_RETRY_TIMER_FOUND",flush=True); raise SystemExit(23)
